"""Educación Financiera EPJA Media N1 y N2, módulo 3 (parte 1): deudas, costos reales y conveniencia de endeudarse. OAD-09 a OAD-12. Todo en papel; cifras inventadas y rotuladas como de ejemplo; sin tasas, comisiones, impuestos ni plazos legales reales."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = ("Papel, lápiz y goma. Los contratos, boletas, tablas y casos vienen escritos en cada ficha y sus cifras son de ejemplo, inventadas; "
             "no se usa dinero real, calculadora real ni internet. Las herramientas informáticas se muestran como resultados ya escritos. "
             "Nada de esto es consejo financiero personal: para una decisión real, pide información a la institución y lee tu contrato.")
build = make_build(MATERIALS)

O9, O10, O11, O12 = (f"EPJA-EFIN-NM1y2-OAD-{n}" for n in ("09", "10", "11", "12"))
PRIOR = ["Conozco el vuelto, las cuotas y las cuentas del hogar de mi vida diaria.", "Sé sumar, restar y multiplicar cantidades en pesos."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=op, reinforce=rf, extend=ex_)


